class Battery:
    def __init__(self, charge):
        self.charge = charge

    def use(self, amount):
        self.charge -= amount
        return self.charge

class Arm:
    def wave(self):
        return "*waves*"

class Robot:
    def __init__(self, name):
        self.name = name
        self.battery = Battery(100)    # a Robot HAS a battery
        self.arm = Arm()               # ...and HAS an arm

    def greet(self):
        left = self.battery.use(10)    # hand the job to a part
        return f"{self.name} {self.arm.wave()} ({left}% left)"

zap = Robot("Zap")
print(zap.greet())
print(zap.greet())
zap.battery = Battery(50)              # swap in a different part
print(zap.greet())

