class Pet:
    def __init__(self, name, kind):
        self.name = name
        self.kind = kind

    def __str__(self):
        return f"{self.name} the {self.kind}"

class Shelter:
    def __init__(self, town):
        self.town = town
        self.pets = []          # HAS pets

    def admit(self, pet):
        self.pets.append(pet)

    def count(self, kind):
        return sum(1 for p in self.pets if p.kind == kind)

    def report(self):
        print(f"{self.town} shelter:")
        for pet in self.pets:
            print(" -", pet)    # Pet.__str__
        print("dogs:", self.count("dog"))  # method -> method

home = Shelter("Elmwood")
home.admit(Pet("Rex", "dog"))
home.admit(Pet("Tom", "cat"))
home.admit(Pet("Bo", "dog"))
home.report()

